// #cddab4 (6a993d6920b26e2d36cddab4) «פיתוח: רשימת מועמדים עם חיפוש, סינון ופעולות מהירות» — принят 2026-11-17.
// /candidates: 4 фильтра (תפקיד, סימולציה, מנהל מגייס, סטטוס) + поиск по имени; опции из данных списка; счётчик «מציג x–y מתוך N»;
// фильтры комбинируются; состояние в URL переживает reload; пустой результат + «ניקוי החיפוש והסינון»; 10 колонок; нет «⋮»;
// «ביצוע» в одну строку (строка 53px); «לדוח» ведёт в отчёт этого кандидата; 390 без горизонтального скролла;
// быстрые действия business по статусу (44×44). Кейсы CAND-014..CAND-017. ТОЛЬКО ЧТЕНИЕ (кнопки копирования/продления/сброса не нажимаются) — @prod-safe.
// Роли: recruiter = auth/user.json («апвпп», testim), business = auth/bizt.json (testim). Числа не зашиты: ожидания берутся из list_candidates и обхода списка.
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { openWithApi } from '../support/api';
import {
  FILTERS, TXT, filterSelect, filterOptions, readCounter, counterTotal, readTable, colIndex, managerCells,
  walkAll, rowsOf, searchBox, openList, noOverflow, resetToFirstPage,
} from './list-support';

const HASH = '#cddab4';
const ROLES = [
  { session: 'user', label: 'recruiter (апвпп)' },
  { session: 'bizt', label: 'business (testim)' },
] as const;

async function apiRows(page: Page): Promise<{ id: string; full_name: string }[]> {
  const api = await openWithApi(page, '/candidates');
  const res = await api.rpc('list_candidates');
  expect(res.status(), `list_candidates: ${await res.text()}`).toBe(200);
  return res.json();
}

for (const role of ROLES) {
  test.describe(`Список кандидатов: поиск и фильтры — ${role.label} (${HASH})`, () => {
    test(`${role.label}: 4 фильтра есть; опции «מנהל מגייס» = менеджеры из данных списка; выбор менеджера оставляет только его строки, счётчик = числу отфильтрованных @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
      const page = await asUser(role.session);
      const list = await apiRows(page);
      await openList(page);

      // Источник: AC3 — фильтры תפקיד, סימולציה, מנהל, סטטוס; решение/реджект 3 (17.11): 4 фильтра вместе с поиском.
      await expect(searchBox(page)).toBeVisible();
      for (const f of FILTERS) await expect(await filterSelect(page, f), `фильтр «${f}»`).toBeVisible();

      // Источник: AC «объём списка» — всего в счётчике = число строк list_candidates этой роли.
      const c0 = (await readCounter(page))!;
      expect(c0.total, 'итог счётчика без фильтров = число строк list_candidates').toBe(list.length);

      // Данные: обход всех страниц без фильтра → менеджеры и их количество (не фиксированные числа).
      const all = await walkAll(page);
      expect(all.rows.length).toBe(list.length);
      const mi = colIndex(all, /מגייס/);
      expect(mi, `колонка «מגייס» (заголовки: ${all.headers.join(' | ')})`).toBeGreaterThanOrEqual(0);
      const counts = new Map<string, number>();
      for (const r of all.rows) if (r[mi] && r[mi] !== '—') counts.set(r[mi], (counts.get(r[mi]) || 0) + 1);
      expect(counts.size, 'в списке есть строки с менеджером').toBeGreaterThan(0);

      await resetToFirstPage(page);
      const mgr = await filterSelect(page, 'מנהל מגייס');
      const opts = await filterOptions(mgr);
      // Источник: реджект 3 — опции «מנהל מגייס» = рекрутёры из списка пользователя.
      for (const name of counts.keys()) expect(opts.map((o) => o.text), `опция для «${name}»`).toContain(name);

      for (const o of opts.filter((x) => counts.has(x.text))) {
        await mgr.selectOption(o.value);
        const want = counts.get(o.text)!;
        const c = await counterTotal(page, want);
        // Источник: AC3 «сколько найдено» — счётчик = числу отфильтрованных строк (на странице: to-from+1 строк).
        await expect(rowsOf(page)).toHaveCount(c.to - c.from + 1);
        expect(c.total).toBe(want);
        const cells = await managerCells(page);
        expect(cells.length).toBeGreaterThan(0);
        for (const v of cells) expect(v, `строка в фильтре «${o.text}»`).toBe(o.text);
        await mgr.selectOption({ index: 0 });
        await counterTotal(page, list.length);
      }
    });

    test(`${role.label}: фильтры комбинируются между собой и с поиском @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
      const page = await asUser(role.session);
      await openList(page);
      const total = (await readCounter(page))!.total;
      const mgr = await filterSelect(page, 'מנהל מגייס');
      const status = await filterSelect(page, 'סטטוס');
      const mOpt = (await filterOptions(mgr))[0];
      test.skip(!mOpt, 'нет вариантов фильтра «מנהל מגייס»');

      await mgr.selectOption(mOpt.value);
      await expect.poll(async () => (await readCounter(page))?.total).toBeLessThanOrEqual(total);
      const byMgr = (await readCounter(page))!.total;

      // Источник: AC3 «работают параллельно» — менеджер + статус: итог не больше, строки соответствуют обоим условиям.
      let combined = 0;
      for (const s of await filterOptions(status)) {
        await status.selectOption(s.value);
        await expect(status).toHaveValue(s.value);
        await expect.poll(async () => (await readCounter(page)) !== null || (await page.getByText(TXT.empty).isVisible())).toBe(true);
        const c = await readCounter(page);
        const n = c ? c.total : 0;
        expect(n, `менеджер «${mOpt.text}» + статус «${s.text}»`).toBeLessThanOrEqual(byMgr);
        if (n > 0) {
          combined++;
          for (const v of await managerCells(page)) expect(v).toBe(mOpt.text);
          await expect(rowsOf(page)).toHaveCount(c!.to - c!.from + 1);
        } else {
          await expect(page.getByText(TXT.empty)).toBeVisible();
        }
      }
      expect(combined, 'нашлась хотя бы одна комбинация менеджер+статус с результатами').toBeGreaterThan(0);
      await status.selectOption({ index: 0 });
      await counterTotal(page, byMgr);

      // Поиск по имени вместе с фильтром менеджера: имя первой строки.
      const t = await readTable(page);
      const name = t.rows[0][0].split('\n')[0].trim();
      await searchBox(page).fill(name);
      await expect.poll(async () => (await readCounter(page))?.total).toBeLessThanOrEqual(byMgr);
      const c = (await readCounter(page))!;
      expect(c.total).toBeGreaterThan(0);
      for (const r of (await readTable(page)).rows) expect(r[0]).toContain(name);
      for (const v of await managerCells(page)) expect(v).toBe(mOpt.text);
    });

    test(`${role.label}: состояние поиска и фильтров в URL переживает перезагрузку @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
      const page = await asUser(role.session);
      await openList(page);
      const mgr = await filterSelect(page, 'מנהל מגייס');
      const opt = (await filterOptions(mgr))[0];
      test.skip(!opt, 'нет вариантов фильтра «מנהל מגייס»');
      await mgr.selectOption(opt.value);
      await expect.poll(() => new URL(page.url()).search, { message: 'фильтр записан в URL' }).not.toBe('');
      const c1 = (await readCounter(page))!;
      const rows1 = (await managerCells(page)).length;
      const url = page.url();

      // Источник: AC2 — состояние фильтра хранится в URL.
      await page.reload();
      await expect(page.getByTestId('pagination-range')).toHaveText(/^מציג \d/, { timeout: 30_000 });
      expect(page.url()).toBe(url);
      await expect(await filterSelect(page, 'מנהל מגייס')).toHaveValue(opt.value);
      expect(await readCounter(page)).toEqual(c1);
      expect((await managerCells(page)).length).toBe(rows1);

      // Поиск тоже в URL.
      const q = (await readTable(page)).rows[0][0].split('\n')[0].trim();
      await searchBox(page).fill(q);
      await expect.poll(() => decodeURIComponent(page.url())).toContain(q);
      await page.reload();
      await expect(searchBox(page)).toHaveValue(q);
    });

    test(`${role.label}: пустой результат — «${TXT.empty}» и «${TXT.clear}» сбрасывает поиск и фильтры @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
      const page = await asUser(role.session);
      await openList(page);
      const total = (await readCounter(page))!.total;
      const mgr = await filterSelect(page, 'מנהל מגייס');
      const opt = (await filterOptions(mgr))[0];
      if (opt) await mgr.selectOption(opt.value);
      await searchBox(page).fill(`QA-AUTO-NO-SUCH-${Date.now()}`);

      // Источник: AC5 — пустое состояние + «ניקוי מסננים» (в UI «ניקוי החיפוש והסינון»).
      await expect(page.getByText(TXT.empty)).toBeVisible();
      await expect(rowsOf(page)).toHaveCount(0);
      const clear = page.getByRole('button', { name: TXT.clear });
      await expect(clear).toBeVisible();
      await clear.click();
      await expect(page.getByText(TXT.empty)).toHaveCount(0);
      await expect(searchBox(page)).toHaveValue('');
      if (opt) await expect(mgr).toHaveValue('');
      for (const f of FILTERS) await expect(await filterSelect(page, f)).toHaveValue('');
      await counterTotal(page, total);
      expect(new URL(page.url()).search, 'URL без параметров поиска/фильтров').toBe('');
    });
  });
}

test.describe(`Список кандидатов: колонки, статусы, «לדוח», 390 — recruiter (${HASH})`, () => {
  test(`recruiter: 10 колонок данных, нет «⋮», «ביצוע» в одну строку, высота строки 53 @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('user');
    await openList(page);
    const t = await readTable(page);
    // Источник: AC1 — 10 колонок.
    const heads = t.headers.filter((h) => h);
    expect(heads, `колонки: ${heads.join(' | ')}`).toHaveLength(10);
    expect(new Set(heads).size).toBe(10);
    // Источник: реджект 1 / Figma 678:652 — быстрые действия значками, без «⋮».
    await expect(page.locator('main').getByText('⋮')).toHaveCount(0);
    await expect(page.getByRole('button', { name: /^פעולות/ })).toHaveCount(0);

    // Источник: реджект 2 / Figma 678:652 — статус в ячейке «ביצוע» в одну строку, строка 53px.
    const rows = rowsOf(page);
    const n = await rows.count();
    expect(n).toBeGreaterThan(0);
    const bad: string[] = [];
    for (let i = 0; i < n; i++) {
      const m = await rows.nth(i).evaluate((tr) => {
        const cell = tr.querySelector('td[data-label="ביצוע"]') as HTMLElement | null;
        const tops = new Set<number>();
        if (cell) {
          const r = document.createRange();
          r.selectNodeContents(cell);
          [...r.getClientRects()].filter((x) => x.width > 0 && x.height > 0).forEach((x) => tops.add(Math.round(x.top / 6)));
        }
        return { h: tr.getBoundingClientRect().height, lines: tops.size, hasCell: !!cell, text: cell?.innerText ?? '' };
      });
      if (!m.hasCell) bad.push(`строка ${i + 1}: нет td[data-label=ביצוע]`);
      else if (m.lines !== 1 || m.text.includes('\n')) bad.push(`строка ${i + 1}: «ביצוע» в ${m.lines} строк(и): ${m.text}`);
      if (Math.abs(m.h - 53) > 1) bad.push(`строка ${i + 1}: высота ${m.h}`);
    }
    expect(bad).toEqual([]);
  });

  test(`recruiter: «לדוח» открывает отчёт именно этого кандидата @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('user');
    const list = await apiRows(page);
    await openList(page);
    const report = (row: ReturnType<typeof rowsOf>) =>
      row.getByRole('link', { name: /^(לדוח|מעבר לדוח)/ }).or(row.getByRole('button', { name: /^(לדוח|מעבר לדוח)/ })).first();
    const rows = rowsOf(page);
    const n = await rows.count();
    let picked = -1;
    for (let i = 0; i < n && picked < 0; i++) {
      await rows.nth(i).hover();
      if (await report(rows.nth(i)).count()) picked = i;
    }
    expect(picked, 'на первой странице есть строка с действием «לדוח»').toBeGreaterThanOrEqual(0);
    const cellName = ((await readTable(page)).rows[picked][0] || '').split('\n')[0].trim();
    const cand = list.find((c) => cellName.startsWith(c.full_name) || c.full_name.startsWith(cellName));
    expect(cand, `кандидат «${cellName}» есть в list_candidates`).toBeTruthy();
    await rows.nth(picked).hover();
    await report(rows.nth(picked)).click();

    // Источник: דרישה 8 — «לדוח» ведёт прямо в отчёт этого кандидата.
    await page.waitForURL(new RegExp(`/candidates/${cand!.id}/report`));
    await expect(page.getByText(cand!.full_name).first()).toBeVisible({ timeout: 30_000 });
  });

  test(`recruiter: 390 — нет горизонтальной прокрутки, 4 фильтра ниже поиска @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('user');
    await openList(page, { width: 390, height: 844 });
    // Источник: комментарий программиста 17.11 / AC «390: фильтры уходят в строки под поиском».
    const o = await noOverflow(page);
    expect(o.sw, 'горизонтальная прокрутка страницы').toBeLessThanOrEqual(o.cw);
    const search = await searchBox(page).boundingBox();
    expect(search).toBeTruthy();
    for (const f of FILTERS) {
      const b = await (await filterSelect(page, f)).boundingBox();
      expect(b, `фильтр «${f}» виден`).toBeTruthy();
      expect(b!.y, `фильтр «${f}» ниже поиска`).toBeGreaterThanOrEqual(search!.y + search!.height - 1);
      expect(b!.x).toBeGreaterThanOrEqual(0);
      expect(b!.x + b!.width).toBeLessThanOrEqual(390 + 1);
    }
    const c = await readCounter(page);
    expect(c, 'счётчик виден').toBeTruthy();
  });
});

test.describe(`Список кандидатов: быстрые действия по статусу — business (${HASH})`, () => {
  const ACT = {
    copy: /^העתקת קישור/,
    extend: /^הארכת תוקף/,
    reset: /^איפוס ניסיון/,
    report: /^(לדוח|מעבר לדוח)/,
  };
  type Key = keyof typeof ACT;
  // Источник: AC4 / דר.3,6,8 + решение 04.11 (по статусу): link-created → copy+extend; expired → extend; тех.сбой/завершён → reset+report.
  const RULES: { status: RegExp; title: string; want: Key[] }[] = [
    { status: /קישור נוצר/, title: 'קישור נוצר', want: ['copy', 'extend'] },
    { status: /פג תוקף/, title: 'פג תוקף', want: ['extend'] },
    { status: /תקלה טכנית/, title: 'תקלה טכנית', want: ['reset', 'report'] },
    { status: /הושלמ/, title: 'הושלמה', want: ['reset', 'report'] },
  ];

  test(`business: значки действий строки по статусу, 44×44, без «⋮» (кнопки не нажимаются) @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('bizt');
    await openList(page);
    await expect(page.locator('main').getByText('⋮')).toHaveCount(0);
    const all = await walkAll(page);
    const si = colIndex(all, /ביצוע/);
    expect(si, 'колонка «ביצוע»').toBeGreaterThanOrEqual(0);
    await resetToFirstPage(page);

    const problems: string[] = [];
    const seen = new Set<string>();
    for (let guard = 0; guard < 30; guard++) {
      const rows = rowsOf(page);
      const n = await rows.count();
      for (let i = 0; i < n; i++) {
        const row = rows.nth(i);
        const status = ((await row.locator('td[data-label="ביצוע"]').innerText()) || '').trim();
        const rule = RULES.find((r) => r.status.test(status));
        if (!rule) continue;
        seen.add(rule.title);
        await row.hover();
        const name = (await row.locator('td').first().innerText()).split('\n')[0].trim();
        for (const k of Object.keys(ACT) as Key[]) {
          const el = row.getByRole('button', { name: ACT[k] }).or(row.getByRole('link', { name: ACT[k] })).first();
          const present = (await el.count()) > 0;
          if (present !== rule.want.includes(k)) problems.push(`«${name}» (${rule.title}): действие ${k} ${present ? 'есть' : 'нет'}, ожидалось ${rule.want.includes(k) ? 'есть' : 'нет'}`);
          if (present && rule.want.includes(k)) {
            const b = await el.boundingBox();
            if (!b || Math.abs(b.width - 44) > 0.6 || Math.abs(b.height - 44) > 0.6) problems.push(`«${name}»: ${k} ${b ? `${b.width}×${b.height}` : 'нет размера'}, ожидалось 44×44`);
          }
        }
      }
      const c = await readCounter(page);
      const next = page.getByRole('button', { name: 'הבא' }).first();
      if (!c || c.to >= c.total || !(await next.isEnabled())) break;
      await next.click();
      await expect.poll(async () => (await readCounter(page))?.from).toBe(c.to + 1);
    }
    expect(problems).toEqual([]);
    expect(seen.size, `в данных testim есть строки хотя бы одного из статусов (найдены: ${[...seen].join(', ') || 'нет'})`).toBeGreaterThan(0);
  });
});
